     "title": "לבדוק: \"חריגה צפויה\" — הווידג׳ט תחזית התזרים מול היתרה והחריגה בפס העליון (מי צודק?)",
     "what": "גבדור (105) בסטייג׳ינג: הפס העליון אומר \"אין חריגה צפויה ב-30 הימים הקרובים\", והווידג׳ט \"תחזית תזרים\" מתחתיו מסמן \"חריגה צפויה\" עם −172,785 ₪. הנתונים (get-cashflow-widget-data): יתרת פתיחה −266,228, מסגרת −268,800, ימים: 06.09 −119,999 · 10.09 −172,785 · 22.09 −142,785 · 02.10 −194,065. הפס עובד לפי \"היתרה החזויה מתחת למסגרת המאושרת\" → אין חריגה; הווידג׳ט מסמן לפי כלל אחר. לבדוק: (1) מה הכלל הנכון לחריגה — מתחת למסגרת או מתחת לאפס? (2) האם היתרה בפס נכונה מול הבנק? (3) האם המספרים בווידג׳ט נכונים? לכתוב כאן מי צודק, ואז פריט לעידו לתקן את הצד השני.ממצאי פיתוח — עידו, 06.09.2026:הכלל באפיון TASK.md סעיף ג הוא יתרה מאוחדת חזויה מתחת למסגרת המאושרת, לא מתחת לאפס. נמצאה שגיאת איחוד בשרת: יתרת הפתיחה והמסגרת סוכמו מארבעה חשבונות, אך תשובת התחזית המאוחדת של Bizibox השמיטה חשבונות ותנועות. לפיכך גם היתרות העתידיות בפס וגם בווידג׳ט לא היו תחזית מאוחדת נכונה.התיקון מבקש תחזית לכל חשבון בנפרד, מאחד יתרות יומיות ומחשב חריגה מול המסגרת של אותם חשבונות. הווידג׳ט מציג את סכום יום החריגה הראשון, בהתאמה לפס. תוקנו גם יום ללא תנועות, התאוששות במהלך היום וגבולות טווח בעת מעבר שעון.קריאות אמיתיות לקריאה בלבד מול Bizibox אומתו לכל ארבעת החשבונות: יתרת פתיחה ‎-266,228 ₪, מסגרת ‎-268,800 ₪, חריגה ראשונה ב-06.09 עם יתרה ‎-286,148 ₪; יתרת סוף 14 יום ‎-510,001 ₪ וסוף 30 יום ‎-658,997 ₪. הסכומים נכונים לתשובת המקור בזמן הבדיקה. שלושה חשבונות מסומנים אצל הספק כלא מעודכנים מזה 2–3 ימים; לא אומתה יתרה חיה באתרי הבנקים.קוד התיקון: שרת 7b9c3bc, קליינט f9ae24c. עברו בדיקות תרחישים ממוקדות מול השירות והרכיבים, TypeScript, build ו-15 הבדיקות הקיימות. הבדיקה הפיננסית של אופיר ואימות הממשק בכניסת CUSTOMER נשארים פתוחים.עדכון פריסה — 06.09.2026: שרת 7b9c3bc וקליינט f9ae24c נפרסו בהצלחה ל-stg. פריסת Firebase הסתיימה בהצלחה בריצה 34055334498. אימות CUSTOMER והבדיקה הפיננסית נשארים פתוחים כמפורט לעיל.אימות ממשק חי — עידו, 06.09.2026: בקישור preview=client1:customer שסיפק עידו לחברה 105, הפס העליון, היום הראשון בתחזית והווידג׳ט \"חריגה צפויה — עו״ש מאוחד\" הציגו כולם יתרה ‎-286,148 ₪ ל-06.09. יתרת פתיחה ‎-266,228 ₪ ומסגרת ‎268,800 ₪ תואמות. נבדקו טווחי 14 יום (סוף ‎-510,001 ₪) ו-30 יום (סוף ‎-658,997 ₪). חוסר ההתאמה בממשק תוקן ואומת. נשארת הבדיקה הפיננסית של אופיר מול נתוני הבנקים ועדכניות המקור, כפי שתועד לעיל.",
