     "title": "זיכרון הלקוח לא מתמלא מקבוצות הוואטסאפ — לוודא שהמסלול רץ",
     "what": "אייל 09.09 ביקש לוודא שזיכרון הלקוח מתמלא מקבוצת הוואטסאפ.\n\n**בדקתי בפרודקשן, וזו התשובה: לא.** סריקה של לוח הזיכרון ב-25 חברות דרך `GET /api/profile-categories/{id}/board` החזירה 54 שורות זיכרון עם מקור, **וכולן `source_type: \"meeting_summary\"`**. אפס שורות מקבוצות הוואטסאפ.\n\n**זה מפתיע במיוחד כאן**, כי בקבוצות רץ כבר תהליך לילי שמייצר סיכום יומי — ראינו אותו הבוקר במסך של \"משרד HK\", עם ניתוח מפורט של מי אמר מה. כלומר התוכן נקרא ומנותח מדי לילה — אבל שום דבר ממנו לא נכנס לזיכרון החברה.",
     "need": "**התשתית בצד התצוגה מוכנה.** `CustomerMemoryBoard.tsx` מזהה ארבעה ערוצים — `meeting`, `call`, `whatsapp`, `chat` — ומצייר לכל אחד תווית. מה שלא קורה הוא הייצור.\n\n**מה לבדוק:**\n1. **האם הסיכום הלילי של הקבוצה מוזן בכלל לתהליך שמייצר זיכרון**, או שהוא נעצר אחרי שהוא נכתב למסך.\n2. אם הוא מוזן — למה לא נוצרות שורות: הפרומפט לא מחזיר, הכתיבה נכשלת, או שהתוכן מסונן בדרך.\n3. **מה נכנס ומה לא.** קבוצה מכילה גם רעש — \"תודה\", \"בסדר\", תיאומים. הזיכרון אמור לקלוט את מה שמשנה את התמונה: לחץ תזרימי, תלונה, החלטה, שינוי בעסק. **לא כל הודעה היא שורת זיכרון.**\n4. **הפרדת המעגלים.** לפי `MEMORY_SPEC.md`, מה שנוגע לאדם ולא לכסף אינו נחשף ללקוח. תוכן שנקלט מקבוצה שהלקוח יושב בה חייב להיכנס לקטגוריה הנכונה, אחרת הוא עלול לחזור אליו דרך הצ׳אט שלו.\n\n**קשור ל-#320** — שם אותו ממצא בדיוק לגבי שיחות טלפון. סביר שזו סיבה אחת לשני הערוצים; שווה לבדוק אותם יחד.\n\n**בדיקה:** קבוצת וואטסאפ פעילה שבה נאמר משהו מהותי מייצרת לפחות שורת זיכרון אחת, מסומנת בתווית \"WhatsApp\", ובקטגוריה הנכונה לפי מעגל החברה או מעגל האדם.",
     "sev": "",
     "dev": "עומרי",
     "who": "",
     "status": "open",
     "imgA": "",
     "capA": "",
     "imgB": "",
     "capB": "",
