     "what": "לבדוק: **1 · סדר הרינדור.** הסיכום הלילי הוצג *לפני* ההודעות של היום שהוא מסכם. הוא נכתב ב-02:00 על היום שהסתיים, ולכן הוא סוגר את היום ולא פותח אותו. הבלוק של `day.summary` עבר מתחת ל-`day.messages.map(...)`. הודעות היום הבא מתחילות מתחתיו, כמו בוואטסאפ.\n\n**2 · גלילה לתחתית.** הלוגיקה הייתה קיימת אבל רצה פעם אחת, לפני שהפריסה התייצבה — שורות נשברות וכרטיס הסיכום נפתח, הגובה גדל, והכניסה לקבוצה נחתה באמצע. נוספה חזרה על הגלילה ב-`requestAnimationFrame`.\n\nהעוגן שגולל אל סיכום מסוים (`data-communication-summary`) לא הושפע — הוא מחפש לפי מזהה ולא לפי מיקום. (נבנה על ידי עידו)",
