     "kind": "check",
     "title": "אחרי הלידיעה — להוציא את המקליט מ-MeetingsPanel לספק גלובלי ופס הקלטה",
     "what": "לבדוק: **המדידה שעשינו לפני שפנינו אליך:**\n\n| | |\n|---|---|\n| `MeetingsPanel.tsx` | 6,118 שורות |\n| `AudioRecorder` בתוכו | 1,291 שורות · 11 `useRef` · 26 `useCallback` · 6 `useEffect` · 5 קריאות שרת |\n| מייבאים את הקובץ | `Dashboard`, `MyProcessPanel`, `WorkspaceBody`, `WorkspacePhoneCalls` |\n\nאחד־עשר ה-`useRef` מחזיקים `MediaRecorder` חי, זרמי מדיה, טיימרים ותור מקטעים שעולים לשרת. זה לא state שאפשר להעביר ולראות אם מתקמפל.\n\n**למה עצרנו ולא עשינו:**\n1. **באג בהקלטה לא מתגלה במסך** — הוא מתגלה אחרי שיועץ ישב שעה מול לקוח וההקלטה לא נשמרה. אי אפשר להקליט את הפגישה הזאת שוב. זה סוג התקלה היחיד כאן שאין ממנו חזרה.\n2. **קונפליקט מיזוג** — העברה של 1,291 שורות מקובץ שאתה עובד עליו תיצור לך קונפליקט ענק.\n3. **בדיקה אמיתית דורשת סטייג׳** — להקליט, לעצור, לרענן באמצע, לסגור טאב. מול פרודקשן זה אסור.\n\n**מה שאנחנו מציעים, אם וכאשר תחליט לעשות את זה:**\n`RecordingProvider` ברמת האפליקציה שמחזיק את הפגישה המוקלטת, השעון, המקור והמקטעים; פס שמצויר ב-shell מעל ה-router; ו-`MeetingsPanel` הופך לצרכן במקום לבעלים. התמדה ב-`sessionStorage` כדי לשרוד רענון, ונעילה בין טאבים כדי שלא יקליטו פעמיים.\n\n**שלוש שאלות שאתה מכריע:**\n1. להעביר לספק גלובלי — כן או לא?\n2. אם כן — אתה עושה את זה, או אנחנו על בראנץ׳ נפרד ואתה עובר?\n3. מתי, ביחס למה שאתה עובד עליו עכשיו?\n\n**האפיון המלא של המנגנון:** `docs/MEETING_RECORDING_SPEC.md` בריפו mainScreen — מכונת המצבים, תוכן הפס, סימון רגעים ב-Space, הקלטה מהירה, ותשעה מצבי קצה (רענון, סגירת טאב, שני טאבים, כשל באמצע, אין הרשאת מיקרופון).\n\n**מה שכבר עשינו ולא נוגע בתשתית** (על `design/0909`, טרם נדחף): שלושה מצבי הקלטה מפורשים במקום שעון `00:00`; מקור ההקלטה נשמר לפגישה ולא נשאל שוב בהמשך; תיקון `getEffectiveTs`; וכפתור הקלטה מהירה בדשבורד החברה. הפירוט ב-#312 וב-#314. (נבנה על ידי עידו)",
     "need": "",
     "sev": "",
     "dev": "אייל",
     "who": "",
     "status": "open",
     "imgA": "",
     "capA": "",
     "imgB": "",
