     "what": "לבדוק: **1 · שלושה מצבי הקלטה** — `MeetingsPanel.tsx` + `MeetingsPanel.css`.\nהשעון הוצג תמיד, גם במנוחה, ולכן פגישה שהוקלטה ולא נסגרה נראתה כמו `00:00` ליד כפתור \"סיום פגישה\", בלי שום רמז שיש הקלטה פתוחה. עכשיו: **מקליט** → שעון רץ ו\"מקליט פגישה\"; **הוקלט וטרם נסגר** → \"הפגישה הוקלטה · טרם נסגרה\" והכפתור \"סיום פגישה ושליחה לסיכום\"; **אין הקלטה** → \"לחצו כדי להתחיל להקליט\". נוסף `p.recording-state` שתופס את מקום השעון כדי שהמשטח לא יקפוץ בין המצבים.\n\n**2 · הקלטה מהירה בדשבורד החברה** — רכיב חדש `src/pages/workspace/meetings/QuickRecordButton.tsx` (+ css), משובץ ב-`WorkspaceBody.tsx` תחת `case \"dashboard\"`.\nלחיצה יוצרת פגישה ב-`api.createMeeting` עם ברירות מחדל (החברה הנוכחית, השעה עכשיו, כותרת \"שם החברה — תאריך\", בלי משתתפים) ומנווטת אל `/meetings/{id}/transcript?record=1`, כלומר ההקלטה מתחילה מיד. אין טופס ואין בחירת תאריך.\n**מוצג רק כאשר `!customerMode`** — ליועץ ולמנהל התזרים. בעל העסק לא מקליט את היועץ שלו.\n\n**מה שלא נבדק:** לא לחצתי על הכפתור. הלוקאל מחובר לשרת הפרודקשן, ולחיצה הייתה יוצרת פגישה אמיתית אצל לקוח. הרינדור, ההרשאה וה-`tsc` נבדקו; יצירת הפגישה בפועל — לא.\n\n**רקע:** האפיון המלא של המנגנון נמצא ב-`docs/MEETING_RECORDING_SPEC.md` בריפו mainScreen. השלב הבא הוא הוצאת המקליט מ-`MeetingsPanel` לספק גלובלי ופס הקלטה קבוע בראש האפליקציה — שינוי מבני שטרם נעשה. (נבנה על ידי עידו)",
