     "title": "לידיעה — מקור ההקלטה נבחר פעם אחת לפגישה, ותוקנה השעה האפקטיבית",
     "what": "לבדוק: **1 · מקור ההקלטה כבר לא נשאל שוב בהמשך הקלטה.** אייל עצר הקלטה, לחץ להמשיך, והדיאלוג \"בחירת מקור ההקלטה\" חזר. הבחירה נשמרת עכשיו ב-sessionStorage לכל מזהה פגישה (`hk.recordingSource.<id>`), וכל המשך ממשיך באותו מקור בלי לשאול. אם המקור השמור נכשל (טאב נסגר, הרשאה נשללה) — הוא נמחק והדיאלוג חוזר.\n\n**2 · נוסח הדיאלוג שוכתב.** במקום \"בחירת מקור ההקלטה / מיקרופון רגיל / טאב, מסך, תוכנה במחשב\" — \"איך מתקיימת הפגישה? / פגישה פרונטלית / פגישה בזום או בטלפון\", עם שורה שמסבירה שנשאל רק פעם אחת. הבחירה נשארת בתחילת ההקלטה ולא עוברת להגדרות, כי פגישה אחת בזום והשנייה פרונטלית.\n\n**3 · תיקון `getEffectiveTs`.** הפונקציה קיבלה את `scheduled_at` — שכבר נושא שעה — ו**הוסיפה** עליו שעה־ביום; בלי `remind_from_time` היא הוסיפה 23:59, כלומר דחפה כל פגישה כמעט יממה קדימה. בפרודקשן: פגישה מ-08.09 23:30 הוצגה \"בעוד 14 שעות ו-17 דק׳\" ותחת \"פגישות עתידיות\", תשע שעות אחרי שהסתיימה. עכשיו: בלי `remind_from_time` משתמשים ב-`scheduled_at` כמו שהוא, ואיתו מחליפים את שעת־היום באותו יום לפי שעון ישראל במקום להוסיף. הפונקציה משמשת גם למיון, אז הסדר ברשימה מושפע.\n\nאחרי התיקון אותה חברה מציגה \"פגישות עתידיות 0 · פגישות שהתקיימו 26\" במקום 1 ו-25. (נבנה על ידי עידו)",
