     "what": "https://github.com/h-beehive/hk-client/pull/7 — ענף design/company-meetings אל stg, עצמאי (לא תלוי ב-PR אחר). שני קומיטים: (1) תצוגת בעל העסק — שלושה מצבים, בלי שיחות; (2) כל המסך לפי docs/cli/meetings.html: ראש הזירה הנייבי (יום·תאריך, שעה 31px, צ׳יפ מצב, שם, משתתף, נגן-גלולה), הציר (כותרת+ספירה, מקצב, קבוצות עם חץ וסיכום מקופל, ארבעה גווני נקודה, סמן \"עכשיו\"), טאבים עם קו קורל, פס העיבוד, רשימת המשימות, הפוטרים (יועץ / אחרי אישור / בעל העסק), פגישה עתידית ולא-התקיימה, פופאפ הנמענים (420px) ותיאום פגישה מהכרטיס (500px, בלי \"שם לקוח\", שם ברירת מחדל \"פגישה חודשית — {חודש}\"). קבצים: MeetingsPanel.tsx/.css (בלוק CSS אחד בסוף הקובץ בתוך .workspace-meetings-envelope), CreateMeetingDialog.tsx (רק כש-workspaceVariant && !isGlobal), SendSummaryUsersDialog.tsx (prop subtitle/workspaceVariant), Meeting.ts (+external_call_id), client.ts (localhost בלבד).",
