     "what": "בניתי לפי הפרוטוטיפ; ארבעה מקומות שבהם הפרוטוטיפ, האפיון והקליינט לא מסכימים — בחרתי ברירת מחדל וצריך כן/לא:\n1. הציר של בעל העסק: הפרוטוטיפ (r=cli) מסתיר את \"פגישות עתידיות\" ואת סמן \"עכשיו\"; האפיון (טבלה ב׳) אומר \"מלא, אותו ציר\". השארתי מלא.\n2. \"מה סוכם בפגישה\": הפרוטוטיפ מציג רשימה ממוספרת אחת + משימות; הסיכום בשרת הוא 4 סקציות (תמונת מצב / תובנות / חיזוק / החלטות). השארתי את 4 הסקציות בעיצוב החדש; רשימה אחת דורשת שדה summary_points בשרת.\n3. תיאום פגישה: הפרוטוטיפ אומר \"סנכרון ליומן ואזכור ללקוח — אוטומטי\" (בלי מתגים); בקליינט שני מתגים \"אזכור ללקוח\" / \"לסנכרן ליומן\". השארתי את המתגים.\n4. שיחות טלפון בציר של היועץ: הפרוטוטיפ = פגישות בלבד (השיחות במסך השיחות, ‎PR #11‎), אבל במסך השיחות אין אישור סיכום — היועץ מאשר סיכומי שיחה (\"שיחה יוצאת — ממתין לאישורך\") רק דרך הזירה. השארתי את השיחות בציר של היועץ.\n(הפרוטוטיפ לבעל העסק עדיין מציג \"סיכום מוכן\" — סותר את ההכרעה מ-04.09; אעדכן את הפרוטוטיפ, לא צריך הכרעה.)",
