     "kind": "check",
     "title": "זיכרון הלקוח לא נבנה משיחות טלפון — לבדוק אם המסלול רץ בכלל",
     "what": "אייל 09.09 ביקש לבדוק אם זיכרון הלקוח נבנה מתוך שיחות טלפון.\n\n**בדקתי בפרודקשן לפני פתיחת הפריט, וזו התשובה:** סרקתי את לוח הזיכרון של 25 חברות דרך `GET /api/profile-categories/{id}/board`. נמצאו 54 שורות זיכרון עם מקור, **וכולן — 54 מתוך 54 — נושאות `source_type: \"meeting_summary\"`**. אף שורה אחת לא הגיעה משיחת טלפון, מקבוצת וואטסאפ או מהצ׳אט עם העוזר.\n\nכלומר: **הזיכרון נבנה היום מפגישות בלבד.**",
     "need": "**זה לא באג תצוגה.** הקליינט כבר יודע להציג שורה שמקורה בשיחה — `CustomerMemoryBoard.tsx` מזהה ארבעה ערוצים (`meeting`, `call`, `whatsapp`, `chat`) ומצייר לכל אחד תווית משלו. גם הפרוטוטיפ מציג שורות עם `src: 'שיחת טלפון'`. התשתית בצד התצוגה מוכנה — מה שלא קורה הוא הייצור.\n\n**מה לבדוק, לפי הסדר:**\n1. **האם התמלול של שיחת טלפון בכלל מוזן לתהליך שמייצר זיכרון**, או שהמסלול קיים רק לסיכומי פגישות.\n2. אם הוא מוזן — **למה לא נוצרות שורות**: הפרומפט לא מחזיר, הכתיבה נכשלת, או שהשיחות מסוננות בדרך.\n3. **האם זה חל גם על קבוצות הוואטסאפ ועל הצ׳אט** — שני ערוצים נוספים שהקליינט מצייר ושלא נמצא מהם ולו זיכרון אחד. אם התשובה זהה, זו בעיה אחת ולא שלוש.\n\n**למה זה חשוב:** שיחת טלפון היא בדיוק המקום שבו נאמרים הדברים שלא נאמרים בפגישה — לחץ תזרימי, חוסר שביעות רצון, כוונה לעזוב. אם הזיכרון לא נבנה מהן, כל מה שנשען עליו נשען על מקור אחד: הבריף לפגישה, ההכנה, ותשובות העוזר.\n\n**בדיקה:** שיחת טלפון שהוקלטה ותומללה מייצרת לפחות שורת זיכרון אחת, והיא מוצגת בכרטיס עם התווית \"שיחה\".\n\n**הערה על היקף הבדיקה שלי:** 25 חברות מתוך 92, ו-54 שורות. מדגם קטן — אבל אחידות של 100% במקור אחד היא לא מקרית.",
     "sev": "",
     "dev": "עומרי",
     "who": "",
     "status": "open",
     "imgA": "",
     "capA": "",
     "imgB": "",
     "capB": "",
     "created": "09.09.2026 12:25",
     "updated": "09.09.2026 12:35",
