     "what": "https://github.com/h-beehive/hk-client/pull/12 — ענף design/metrics-editor אל stg, עצמאי. שלושה קומיטים: העורך (1180px, שתי עמודות — #51/#101 מהסבב הקודם), התאמה ראשונה של הגיליון, והגיליון+הכרטיס במלואם: רצועה כהה עם גלולת טווח ופופאפ, עמודת מצב עם נקודה, שם נערך במקום, תאים = input תמיד עם Enter/חצים/Esc, כותרות חודש עם [+]/[−] ומפרידי 3px, השורה הריקה, פוטר עם גלולות ימי עבודה ו\"נשמר · HH:MM\", כרטיס המדד (600px: flag, בר 0–125% עם סמן ב-80%, יעד יומי, משפט הפער, מגמה 6 חודשים, \"שאל את העוזר\" → הצ׳אט עם השאלה), \"מחיקת המדד\" בפוטר העורך. קבצים: MetricsPanel.tsx/.css (בלוק CSS אחד לגיליון במקום הישן), WorkspacePanels.css (הדריסות הישנות הוסרו), WorkspaceAiChat.tsx (שאלה מ-location.state), client.ts (localhost בלבד).",
