     "what": "לבדוק: **הבדיקה (GET בלבד, כל 91 החברות שיש להן ווידג׳טים, 304 ווידג׳טים):**\n\n| | |\n|---|---|\n| `order_index` רציף ותקין (0,1,2,…) | בכל 91 החברות, בלי יוצא מן הכלל |\n| ווידג׳טים עם `widget_column_index` שמור | 104 מתוך 304 |\n| חברות שבהן **כל** הווידג׳טים עם עמודה | 22 |\n| חברות שבהן **אף אחד** לא | 65 |\n| **חברות במצב מעורב** | **4** — 312, 470, 474, 514 |\n\nהשרת שומר ומחזיר את הסדר נקי. הבעיה היא בהרכבת הפריסה בקליינט.\n\n**המנגנון:** `getWidgetColumnIndex` נופל, כשאין עמודה שמורה, ל-`index % 2` — כלומר לפי המיקום ברשימה. בחברה מעורבת זה קטלני: ווידג׳ט עם עמודה שמורה נשאר במקומו, וווידג׳ט בלי עמודה קופץ לפי הזוגיות של האינדקס החדש. גוררים ווידג׳ט אחד, כל האינדקסים זזים, וווידג׳טים שלא נגעו בהם מחליפים עמודה.\n\n**למה נוצר מצב מעורב:** `persistWidgetLayout` כתב `widget_column_index` **רק לווידג׳טים שהעמודה שלהם השתנתה** מאז תחילת הגרירה. מי שלא זז לא קיבל עמודה שמורה לעולם, ונשאר תלוי בזוגיות.\n\n**התיקון:** בכל שמירה נכתבת עמודה מפורשת לכל ווידג׳ט — גם למי שלא זז — אלא אם כבר יש לו עמודה שמורה זהה (ואז אין טעם בכתיבה). `buildWidgetLayoutFromColumns` ממילא מציב `widget_column_index` על כל ווידג׳ט לפי העמודה שאליה נגרר, כך שהערך שנשמר הוא המיקום האמיתי ולא הזוגיות.\n\n**מה שלא נבדק:** לא ביצעתי גרירה. הלוקאל מחובר לשרת הפרודקשן, וגרירה הייתה משנה את הפריסה של לקוח אמיתי. הלוגיקה ו-`tsc` נבדקו; ההתנהגות בפועל צריכה בדיקה בסטייג׳.\n\n**הערה:** החברות שכבר במצב מעורב יסתדרו אחרי הגרירה הראשונה שתישמר, כי מאז ייכתבו עמודות לכולן. (נבנה על ידי עידו)",
