     "need": "**הבעיה כפולה, וצריך לטפל בשתיהן:**\n\n**1 · הכשל עצמו.** למה `bizibox_cashflow_accounts` מחזיר `error` עם `payload = NULL`. כמה חברות מושפעות, ומה השגיאה בפועל — היא לא נשמרת בשורה, ולכן אי אפשר לדעת מהטבלה מה קרה. **כדאי לשמור את סיבת השגיאה ב-payload במקום NULL**, אחרת כל אבחון מתחיל מאפס.\n\n**2 · הכשל שקוף.** זו הנקודה החשובה יותר. הסטטוס ברמת הריצה אומר SUCCESS כששירות משנה נפל, ולכן:\n- ביועץ ובמנהל התזרים לא נדלקת שום נורה.\n- החברה נראית מסונכרנת, והתזרים פשוט חסר או ישן.\n- מי שמסתכל על המסך לא יודע שהוא מסתכל על נתון לא שלם.\n\n**ריצה שאחד משירותי המשנה שלה נכשל אינה SUCCESS.** צריך שהסטטוס ישקף את זה, ושהכשל יגיע למסך — לפחות למנהל התזרים.\n\n**ממצא נוסף מאותה בדיקה (קריאות GET בלבד, 92 חברות בפרודקשן):**\n\n| | |\n|---|---|\n| חברות מחוברות לביזיבוקס (`bci`) | 85 מתוך 92 |\n| סנכרון אחרון היום (09.09) | 82 |\n| `FAILED` בריצה האחרונה | **8** |\n| התאריך של כל שמונת הכשלים | **08.07.2026 — לפני חודשיים** |\n\nשמונה חברות נכשלו בסנכרון ביולי **ומאז לא רצה עליהן ריצה נוספת**: מאיה מנצורה (457), משרד HK (174), פלאס וואן (475), חלי קוסמטיקס (477), אסתי ביטון (479), שירן פילאטיס (490), טל מירון (491), מאי סרידרו (492). כלומר אין ניסיון חוזר אחרי כשל — החברה פשוט נושרת מהמחזור ונשארת עם נתונים בני חודשיים.\n\n**בדיקה:** חברה ששירות משנה שלה נכשל אינה מסומנת SUCCESS; סיבת השגיאה נשמרת ב-payload; וחברה שנכשלה נכנסת לניסיון חוזר במחזור הבא במקום להיעלם.",
