     "title": "העוזר AI לא ישלוף נתונים מלפני תאריך תחילת העבודה פחות חודשיים",
     "what": "אייל 09.09: *\"להגביל לפי תאריך תחילת עבודה מינוס חודשיים… ההתייחסות היא ב-AI — שלא יביא נתונים מתחת לתחילת עבודה מינוס חודשיים.\"*\n\nהעוזר שולף היום נתונים פיננסיים בלי גבול תחתון. ללקוח שהצטרף לפני חודשיים קיימת במסד היסטוריה של שנים אחורה — תנועות שאיש לא עבר עליהן ושלא קוטלגו. כשהעוזר נשען עליהן הוא עונה על סמך נתונים שאיננו עומדים מאחוריהם: ממוצעים שמערבבים תקופה שלא ניהלנו, השוואות \"מול שנה שעברה\" שנשענות על זבל, ומגמות שנגזרות ממה שקדם לנו.\n\n**זו לא הגבלה על המסכים** — במסכים היועץ רואה את התאריך ומבין את ההקשר. **זו הגבלה על מה שהעוזר מושך כדי לענות.**",
     "need": "**החוק:** כל שליפת נתונים פיננסיים של העוזר מוגבלת מלמטה ב-`תאריך תחילת עבודה − חודשיים`, פר חברה. מה שקדם לגבול לא נכנס לתשובה, לא לחישוב ולא להקשר.\n\n**איפה זה צריך לחול:**\n- שליפות התנועות והדוחות שמזינות את התשובה.\n- כל חישוב נגזר — ממוצעים, מגמות, השוואות לתקופה קודמת.\n- גם כשהמשתמש מבקש במפורש טווח מוקדם יותר: העוזר לא ממציא ולא שותק, אלא אומר שהנתונים מתחילים מהתאריך הזה ומסביר למה.\n\n**שאלה אחת שנשארה פתוחה ואייל מכריע בה:** מהו \"תאריך תחילת עבודה\"? אין היום שדה כזה בקליינט, ולא מצאתי אזכור שלו בלוח. המועמדים: שדה חדש בהגדרות החברה, `done_date` הקיים, או תאריך יצירת החברה. **אם ההכרעה היא שדה חדש — הוא נפתח קודם בשרת, וזה פריט נפרד לעידו.**\n\n**בדיקה:** לחברה שתחילת העבודה שלה 01.06.2026, שאלה לעוזר על ממוצע ההוצאות מחזירה חישוב שמתחיל ב-01.04.2026 ולא לפני. שאלה מפורשת על ינואר 2026 מקבלת תשובה שאומרת שאין נתונים לפני 01.04.2026 — לא מספר, ולא שתיקה.",
     "sev": "",
