     "need": "**זה לא הקליינט — בדקתי.** הקליינט קורא את הקטגוריה של שורת ההיסטוריה מהמפתחות `categoryName` / `category_name`, וזה המפתח הנכון. אימות מול פרודקשן:\n\n`GET /api/companies/471/operations/unrecognized-checks/464793/history?beneficiaryName=...`\n\nמחזיר שורה תקינה לגמרי:\n```\n{\n  \"transId\": \"562579b7-...\",\n  \"date\": 1783458000000,\n  \"referenceNumber\": \"10842\",\n  \"amount\": 23010,\n  \"direction\": \"in\",\n  \"categoryId\": \"22ab6959-fcee-4809-923c-167828b35c30\",\n  \"categoryName\": \"הכנסות ממכירות\",\n  \"description\": \"א.א.א בניית פתרונות חימום\",\n  \"similarityScore\": 0.724\n}\n```\nכלומר המבנה נכון והקליינט מציג אותו כמו שצריך כשהוא מגיע. במקרה של \"מני מאיה\" השרת מחזיר `categoryName` ריק לתנועה שכן מקוטלגת.\n\n**מה צריך לבדוק:** למה השאילתה של ההיסטוריה לא מביאה את הקטגוריה עבור התנועה הזאת. חשד: הקטגוריה נשלפת רק דרך מסלול אחד (למשל קיטלוג ברמת תנועת הבנק), ותנועה שקוטלגה במסלול אחר — למשל דרך הצ׳ק — לא נתפסת. אותה תנועה מוצגת עם קטגוריה במקום אחר במסך, אז המידע קיים במסד.\n\n**בדיקה:** בפאנל \"היסטוריה ובדיקת התאמה\" של אותו צ׳ק, התנועה של 10.08.2026 על 975 ₪ מציגה \"שכר וסוציאליות\" — אותה קטגוריה שמוצגת ברשימה שלצידה.\n\n**למה זה משנה יותר ממה שנראה:** מאותה תשובה נגזרים `categoryCount` ו-`consistentCategory`, ומהם נבנה הכפתור \"קיטלוג כמו קודם — X\". תנועה שחוזרת בלי קטגוריה מקלקלת את הספירה, ולכן ההצעה האוטומטית לא תופיע גם כשהיא נכונה.",
     "sev": "בינוני",
     "dev": "עידו",
     "who": "",
     "status": "open",
