       "txt": "אייל 09.09 שאל אם זה שרת או קליינט. בהתחלה נטיתי לומר קליינט — הפרסר של שורות ההיסטוריה קורא פחות מפתחות מהפרסרים השכנים לו. בדיקה מול פרודקשן הפריכה את זה: השרת מחזיר categoryName תקין במקרה אחר, כלומר המפתח נכון והקליינט קורא אותו. המסקנה הפוכה — השרת לא מביא את הקטגוריה עבור התנועה הזאת."
