     "title": "מייל קיים חוסם פתיחת איש קשר — צריך לקשר את החשבון הקיים לחברה הנוספת, לא לחסום ולא לשכפל",
     "what": "לבדוק: **הכרעת אייל 08.09: ל-user_account יש תמיד מייל אחד ויחיד — הייחודיות הזאת נשארת.** מה שצריך להשתנות הוא מה קורה כשהמייל כבר קיים: במקום לחסום, לקשר את חשבון המשתמש הקיים כאיש קשר גם בחברה החדשה. אדם אחד, חשבון אחד, כמה חברות.\n\nמצב הנתונים היום סותר את הכלל הזה. בדקתי בסטייג׳ בקריאות GET בלבד, 125 חברות דרך /api/companies/get-company-details/{id}:\n\n• 12 מיילים שונים בלבד יושבים על 125 חברות.\n• **שני מיילים יושבים על יותר מחברה אחת, וכל מופע עם user_id שונה:** מייל אחד על חברות 261, 172, 281 עם user_id 227/331/301; מייל שני על חברות 104, 270 עם user_id 324/231. contact_source=\"users\" בכולם.\n\nכלומר המערכת כבר יצרה בעבר חשבונות כפולים לאותו מייל — בדיוק מה שהכלל אוסר. זו לא רק תקלה בהוספה, אלא גם נתונים שצריך לאחד.\n\nצריך: (1) פתיחת איש קשר עם מייל שכבר קיים לא נחסמת — היא מקשרת את ה-user_account הקיים לחברה הנוספת. (2) לא נוצר חשבון שני לאותו מייל, לעולם. (3) איחוד הכפילויות שכבר במסד (חמשת המופעים שלמעלה) לחשבון אחד לכל מייל, עם שמירת כל שיוכי החברות. (4) לוודא שהתחברות של אדם כזה מציגה לו את כל החברות שהוא משויך אליהן.\n\nבדיקה: פתיחת איש קשר עם מייל שכבר קיים בחברה אחרת עוברת, ואותו user_id מופיע בשתי החברות; אין במסד שני חשבונות עם אותו מייל; ניסיון להוסיף את אותו מייל פעמיים לאותה חברה עדיין נחסם. (נבנה על ידי עידו)",
