     "title": "Jampa · קטגוריות הזיכרון של המטופל — סט נפרד מ-HK (מסמך אפיון מוכן)",
     "what": "היום Jampa מריץ את קטגוריות הזיכרון של HK כמות שהן. מטפל שפותח מטופל רואה בכרטיס \"פרופיל עסקי\", \"מצב תזרימי\" ו\"כאבי לקוח\" — ראה צילום בכרטיס המטופל בסטייג׳. זו לא רק בעיית מינוח: הפרומפט מבקש מה-AI לחלץ מבנה עסקי מתוך שיחה טיפולית, והוא ממלא את מה שהתבקש. כל מה שנבנה מעל הזיכרון (בריף, הכנה לפגישה, תשובות העוזר) יושב על היסוד הזה.",
     "need": "להטמיע את הסט של Jampa לפי docs/JAMPA_MEMORY_SPEC.md (בריפו mainScreen) — שם, תיאור, פרומפט וחשיפה לכל קטגוריה כתובים שם מילה במילה. (1) טבלת הקטגוריות מקבלת שיוך למותג — הקטגוריות של HK (business_profile, cashflow_status, customer_pains, goals_agreements, material_events, collaboration) אינן חלות על business_type_id=2. (2) שמונה קטגוריות למטופל: פרופיל אישי, מה הביא אותו, מטרות והסכמות, דפוסים חוזרים, מה עובד ומה לא, אירועים מהותיים, הברית הטיפולית, דגלים קליניים. (3) \"דגלים קליניים\" — chat_exposure נעול על \"לא נחשף\", לא ניתן לשינוי מהממשק, ולא נכנס לשום סיכום שנשלח למטופל. (4) מסך \"קטגוריות הזיכרון\" בניהול מציג את הסט לפי המותג. אין שינוי ב-HK. בדיקה: מטופל ב-Jampa מציג שמות קטגוריות טיפוליות בלבד; לקוח ב-HK מציג את שש הקטגוריות הקיימות ללא שינוי; ניסיון לפתוח \"דגלים קליניים\" לחשיפה נחסם.",
     "sev": "",
     "dev": "עומרי",
